WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC, id) AS dedup_rank FROM inventory) x WHERE dedup_rank = 1) SELECT DATE_TRUNC('YEAR', last_restock) AS year_start, store_id, product_id, APPROX_PERCENTILE(quantity, 0.5) AS quantity_p50, PERCENTILE_APPROX(quantity, 0.5) AS quantity_p50_2, ROUND(AVG(quantity), 2) AS avg_quantity, COUNT(DISTINCT id) AS distinct_ids FROM deduped GROUP BY DATE_TRUNC('YEAR', last_restock), store_id, product_id ORDER BY quantity_p50 DESC NULLS FIRST
